//! A small URL parser matching the observable behavior of the C++ version.

/// Parsed components of a URL.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Url {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
}

impl Url {
    /// Parses `input` into its URL components.
    pub fn new(input: String) -> Self {
        let mut rest = input;

        // A fragment starts at the first '#' and is discarded before parsing
        // the remaining components.
        if let Some(fragment_start) = rest.find('#') {
            rest.truncate(fragment_start);
        }

        // The query starts at the first '?' that remains after removing the
        // fragment. Later '?' characters are ordinary query data.
        let mut query = String::new();
        if let Some(query_start) = rest.find('?') {
            query = rest[query_start + 1..].to_owned();
            rest.truncate(query_start);
        }

        // The original parser recognizes the literal "://" separator without
        // validating which characters appear in the scheme.
        let scheme_start = rest.find("://");
        let has_scheme = scheme_start.is_some();
        let mut scheme = String::new();
        if let Some(start) = scheme_start {
            scheme = rest[..start].to_ascii_lowercase();
            rest.drain(..start + 3);
        }

        let mut host = String::new();
        let mut path = String::new();
        if has_scheme {
            if let Some(path_start) = rest.find('/') {
                host = rest[..path_start].to_owned();
                path = rest[path_start..].to_owned();
            } else {
                host = rest;
            }
        } else {
            // Without a scheme separator, the remaining text is the path.
            path = rest;
        }

        // Only the first '@' is treated as the end of user information.
        if let Some(userinfo_end) = host.find('@') {
            host.drain(..userinfo_end + 1);
        }

        // A plain colon split is used. This intentionally does not special-
        // case IPv6 addresses, matching the behavior of the C++ program.
        let mut port = -1;
        if let Some(port_start) = host.find(':') {
            let port_text = host[port_start + 1..].to_owned();
            host.truncate(port_start);
            if let Some(parsed_port) = parse_stoi_prefix(&port_text) {
                if (0..=65535).contains(&parsed_port) {
                    port = parsed_port;
                }
            }
        }

        Self {
            scheme,
            host,
            port,
            path,
            query,
        }
    }

    /// Returns the lower-cased scheme, or an empty string.
    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    /// Returns the host, or an empty string.
    pub fn host(&self) -> &str {
        &self.host
    }

    /// Returns the port, or -1 when absent or invalid.
    pub fn port(&self) -> i32 {
        self.port
    }

    /// Returns the path, or an empty string.
    pub fn path(&self) -> &str {
        &self.path
    }

    /// Returns the query, or an empty string.
    pub fn query(&self) -> &str {
        &self.query
    }
}

/// Parses the initial decimal integer accepted by C++ `std::stoi(text)`.
///
/// Leading C-locale whitespace and one sign are accepted, parsing stops at
/// the first non-digit, and values outside the C++ `int` range are rejected.
fn parse_stoi_prefix(text: &str) -> Option<i32> {
    let bytes = text.as_bytes();
    let mut index = 0;

    while index < bytes.len() && matches!(bytes[index], b' ' | b'\t' | b'\n' | b'\v' | b'\f' | b'\r') {
        index += 1;
    }

    let negative = if index < bytes.len() && (bytes[index] == b'+' || bytes[index] == b'-') {
        let is_negative = bytes[index] == b'-';
        index += 1;
        is_negative
    } else {
        false
    };

    if index == bytes.len() || !bytes[index].is_ascii_digit() {
        return None;
    }

    let limit = if negative { 2_147_483_648_i64 } else { 2_147_483_647_i64 };
    let mut magnitude = 0_i64;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        magnitude = magnitude * 10 + i64::from(bytes[index] - b'0');
        if magnitude > limit {
            return None;
        }
        index += 1;
    }

    if negative {
        Some(-(magnitude as i32))
    } else {
        Some(magnitude as i32)
    }
}

#[cfg(test)]
mod tests {
    use super::Url;

    fn components(input: &str) -> (String, String, i32, String, String) {
        let url = Url::new(input.to_owned());
        (
            url.scheme().to_owned(),
            url.host().to_owned(),
            url.port(),
            url.path().to_owned(),
            url.query().to_owned(),
        )
    }

    #[test]
    fn parses_basic_urls() {
        assert_eq!(
            components("http://example.com:8080/path?x=1#fragment"),
            ("http".into(), "example.com".into(), 8080, "/path".into(), "x=1".into())
        );
        assert_eq!(
            components("https://example.com"),
            ("https".into(), "example.com".into(), -1, String::new(), String::new())
        );
    }

    #[test]
    fn matches_original_edge_cases() {
        assert_eq!(
            components("example.com/path?x=1"),
            (String::new(), String::new(), -1, "example.com/path".into(), "x=1".into())
        );
        assert_eq!(
            components("HTTP://user:pass@example.com:12abc/path#ignored?x"),
            ("http".into(), "example.com".into(), 12, "/path".into(), String::new())
        );
        assert_eq!(
            components("http://example.com:65536"),
            ("http".into(), "example.com".into(), -1, String::new(), String::new())
        );
    }
}

